    private static readonly Dictionary<string, Geometry?> Cache = new Dictionary<string, Geometry?>();

    /// <summary>Le logo de cette plateforme (carré de 24 × 24), ou null s'il n'y en a pas.</summary>
    public static Geometry? Get(string filterKey)
    {
        if (Cache.TryGetValue(filterKey, out Geometry? cached))
        {
            return cached;
        }

        Geometry? geometry = null;

        if (PathData.TryGetValue(filterKey, out string? data) || ConsolePathData.TryGetValue(filterKey, out data))
        {
            try
            {
                geometry = Geometry.Parse(data);
                geometry.Freeze();   // partagée par tous les boutons, jamais modifiée
            }
            catch (FormatException)
            {
                geometry = null;     // tracé illisible : le bouton garde le nom en texte
            }
        }

        Cache[filterKey] = geometry;
        return geometry;
    }
}

/// <summary>
/// Pour le XAML (onglet Comptes) : « Steam » → le logo de Steam.
/// Utilisation : Data="{Binding Source=Steam, Converter={StaticResource PlatformLogo}}".
/// </summary>
public class PlatformLogoConverter : System.Windows.Data.IValueConverter
{
    public object? Convert(object value, Type targetType, object parameter, System.Globalization.CultureInfo culture)
    {
        return value is string key ? PlatformLogos.Get(key) : null;
    }

    public object ConvertBack(object value, Type targetType, object parameter, System.Globalization.CultureInfo culture)
    {
        throw new NotSupportedException();
    }
}
